//! Bash completion is derived from Clap's live command tree, keeping flags in sync.
use std::io::Write;

use anyhow::Result;
use clap::Command;

pub fn bash(mut command: Command, out: &mut impl Write) -> Result<()> {
    command.build();
    writeln!(
        out,
        "# Generated by rustunes completions bash\n_rustunes() {{\n  local cur key='' i word opts\n  cur=\"${{COMP_WORDS[COMP_CWORD]}}\"\n  for ((i=1; i<COMP_CWORD; i++)); do\n    word=\"${{COMP_WORDS[i]}}\"\n    case \"$key:$word\" in"
    )?;
    transitions(&command, "", out)?;
    writeln!(out, "    esac\n  done\n  case \"$key\" in")?;
    choices(&command, "", out)?;
    writeln!(
        out,
        "  esac\n  COMPREPLY=()\n  if [[ \"$cur\" == -* ]]; then\n    mapfile -t COMPREPLY < <(compgen -W \"$opts\" -- \"$cur\")\n  elif [[ -n \"$commands\" ]]; then\n    mapfile -t COMPREPLY < <(compgen -W \"$commands\" -- \"$cur\")\n  fi\n}}\ncomplete -o default -F _rustunes rustunes"
    )?;
    Ok(())
}

fn transitions(command: &Command, key: &str, out: &mut impl Write) -> Result<()> {
    for child in command.get_subcommands().filter(|c| !c.is_hide_set()) {
        let name = child.get_name();
        let next = if key.is_empty() {
            name.to_owned()
        } else {
            format!("{key}/{name}")
        };
        writeln!(out, "      '{}:{}') key='{}' ;;", key, name, next)?;
        transitions(child, &next, out)?;
    }
    Ok(())
}

fn choices(command: &Command, key: &str, out: &mut impl Write) -> Result<()> {
    let mut values = Vec::new();
    for arg in command.get_arguments().filter(|a| !a.is_hide_set()) {
        if let Some(long) = arg.get_long() {
            values.push(format!("--{long}"));
        }
        if let Some(short) = arg.get_short() {
            values.push(format!("-{short}"));
        }
    }
    let commands: Vec<_> = command
        .get_subcommands()
        .filter(|c| !c.is_hide_set())
        .map(|c| c.get_name())
        .collect();
    writeln!(
        out,
        "    '{}') opts='{}'; local commands='{}' ;;",
        key,
        values.join(" "),
        commands.join(" ")
    )?;
    for child in command.get_subcommands().filter(|c| !c.is_hide_set()) {
        let next = if key.is_empty() {
            child.get_name().to_owned()
        } else {
            format!("{key}/{}", child.get_name())
        };
        choices(child, &next, out)?;
    }
    Ok(())
}
